from ..discount.utils.promotion import calculate_discounted_price_for_rules

if price_override is None:
    return channel_listing.discounted_price or channel_listing.price
price: Money = self.get_base_price(channel_listing, price_override)
rules = promotion_rules or []
return calculate_discounted_price_for_rules(
    price=price, rules=rules, currency=channel_listing.currency
)

if has_one_of_permissions(requestor, ALL_PRODUCTS_PERMISSIONS):
    if limited_channel_access:
        if channel:
            channel_listings = (
                ProductChannelListing.objects.using(self.db)
                .filter(channel_id=channel.id)
                .values("id")
            )
            return self.filter(
                Exists(channel_listings.filter(product_id=OuterRef("pk")))
            )
        return self.none()
    return self.all()
if not channel:
    return self.none()

def _resolve_products(channel_obj):
    qs = resolve_products(info, requestor, channel_obj, limited_channel_access)
    if search:
        qs = ChannelQsContext(
            qs=prefix_search(qs.qs, search), channel_slug=channel
        )
    kwargs["channel"] = channel
    qs = filter_connection_queryset(
        qs, kwargs, allow_replica=info.context.allow_replica
    )
    return create_connection_slice(qs, info, kwargs, ProductCountableConnection)

if is_available_for_purchase is not None:
    defaults["available_for_purchase_at"] = (
        cls.get_available_for_purchase_date(
            is_available_for_purchase, update_channel
        )
    )
product_channel_listing, _ = ProductChannelListing.objects.update_or_create(
    product=product, channel=channel, defaults=defaults
)
cls.add_variants(channel, add_variants)

if self.reward_value_type == RewardValueType.FIXED:
    discount_amount = Money(self.reward_value, currency)
    return partial(fixed_discount, discount=discount_amount)
if self.reward_value_type == RewardValueType.PERCENTAGE:
    return partial(
        percentage_discount,
        percentage=self.reward_value,
        rounding=ROUND_HALF_UP,
    )
raise NotImplementedError("Unknown discount type")

applied_discount = None
if available_discounts:
    applied_discount = max(
        [
            (rule_id, price - discount(price))
            for rule_id, discount in available_discounts
        ],
        key=lambda x: x[1].amount,  # sort over a max discount
    )

return applied_discount

if (
    thumbnail := Thumbnail.objects.using(settings.DATABASE_CONNECTION_REPLICA_NAME)
    .filter(format=format, size=size_px, **{instance_id_lookup: pk})
    .first()
):
    return HttpResponseRedirect(thumbnail.image.url)

pk_field = "uuid" if object_type in UUID_IDENTIFIABLE_TYPES else "id"
try:
    instance = model_data.model.objects.using(
        settings.DATABASE_CONNECTION_REPLICA_NAME
    ).get(**{pk_field: pk})
except ObjectDoesNotExist:
    return HttpResponseNotFound("Instance with the given id cannot be found.")
